function BINARY_SEARCH(array, n, target):
    low ← 0
    high ← n - 1

    while low ≤ high:
        mid ← low + (high - low) / 2

        if array[mid] = target:
            return mid
        else if array[mid] < target:
            low ← mid + 1
        else:
            high ← mid - 1

    return NOT_FOUND

