def selection_sort_frames(arr):
    a = arr[:]
    n = len(a)
    frames = []
    for i in range(n - 1):
        min_idx = i
        frames.append({"i": i, "min_idx": min_idx, "j": i, "arr": a[:], "action": "start: min_idx = i"})
        for j in range(i + 1, n):
            frames.append({"i": i, "min_idx": min_idx, "j": j, "arr": a[:], "action": f"comparing arr[j]={a[j]} with current min={a[min_idx]}"})
            if a[j] < a[min_idx]:
                min_idx = j
                frames.append({"i": i, "min_idx": min_idx, "j": j, "arr": a[:], "action": f"min_idx updated -> {min_idx}"})
        if min_idx != i:
            a[i], a[min_idx] = a[min_idx], a[i]
        frames.append({"i": i, "min_idx": i, "j": None, "arr": a[:], "action": f"final swap: arr[{i}] with the found minimum"})
    frames.append({"i": n, "min_idx": None, "j": None, "arr": a[:], "action": "Array is sorted - done"})
    return frames

def show_selection_animation(frames, title):
    def _frame(ax, k):
        fr = frames[k]
        a = fr["arr"]
        colors = [COLOR_DEFAULT] * len(a)
        for idx in range(0, fr["i"]):
            colors[idx] = COLOR_SORTED
        if fr.get("j") is not None:
            colors[fr["j"]] = COLOR_COMPARE_B
        if fr.get("min_idx") is not None and fr["min_idx"] < len(a):
            colors[fr["min_idx"]] = COLOR_MIN
        draw_array(ax, a, colors=colors, title=title, note=fr["action"])
    return run_animation(_frame, n_frames=len(frames), interval=700, figsize=(7.5, 2.9))

